output_text:
[
  {
    "id": "no_cart_in_single_file_shelf_aisles",
    "text": "Shopping carts are prohibited in single-file shelf aisles where shelves border both sides.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "singleFileShelfAisle"
        ]
      }
    }
  },
  {
    "id": "no_enter_single_file_with_cart",
    "text": "An agent must not move a cart into a single-file shelf aisle.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {
        "enterSingleFileAisleWithCart": {
          "pre": {
            "and": [
              "hasCart",
              "MOVE"
            ]
          },
          "post": "singleFileShelfAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enterSingleFileAisleWithCart"
    }
  },
  {
    "id": "park_before_narrow_aisle",
    "text": "At the mouth of a single-file product aisle, a shopper with a cart may not continue north with the cart and must leave it behind instead.",
    "abstraction": {
      "state_properties": {
        "cartParkingMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "cartParkingMouth",
          "hasCart",
          "N"
        ]
      }
    }
  },
  {
    "id": "drop_cart_only_at_aisle_mouth",
    "text": "A shopper may put down or park a cart only at designated mouths of single-file product aisles.",
    "abstraction": {
      "state_properties": {
        "cartParkingMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "dropCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "dropCart",
          {
            "not": "cartParkingMouth"
          }
        ]
      }
    }
  },
  {
    "id": "retrieve_cart_after_narrow_aisle",
    "text": "After returning from a single-file shelf aisle to the cart-parking mouth, the shopper is obliged to retrieve the cart.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        },
        "cartParkingMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "returnFromSingleFileAisle": {
          "pre": {
            "and": [
              "singleFileShelfAisle",
              {
                "not": "hasCart"
              },
              "S"
            ]
          },
          "post": {
            "and": [
              "cartParkingMouth",
              {
                "not": "hasCart"
              }
            ]
          }
        },
        "retrieveCart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "returnFromSingleFileAisle",
      "discharge": "retrieveCart"
    }
  },
  {
    "id": "wide_shelf_pickups_need_cart",
    "text": "Shelf interactions from wide aisles must be done with a cart, while shelf interactions inside single-file aisles are exempt.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        },
        "wideShelfPosition": {
          "and": [
            "adjShelf",
            {
              "not": "singleFileShelfAisle"
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "wideShelfPosition",
          "INTERACT",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "no_walkaway_from_parked_cart",
    "text": "After parking a cart at an aisle mouth, the shopper may not walk away into a wide aisle without the cart.",
    "abstraction": {
      "state_properties": {
        "cartParkingMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "wideAisle": {
          "ge": [
            "freeWidthH",
            6
          ]
        }
      },
      "events": {
        "walkAwayFromParkedCart": {
          "pre": {
            "and": [
              "cartParkingMouth",
              {
                "not": "hasCart"
              },
              "MOVE"
            ]
          },
          "post": {
            "and": [
              "wideAisle",
              {
                "not": "cartParkingMouth"
              }
            ]
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "walkAwayFromParkedCart"
    }
  },
  {
    "id": "one_way_cart_flow_in_wide_corridors",
    "text": "Carts in wide horizontal shopping corridors must follow the one-way flow and may not move west.",
    "abstraction": {
      "state_properties": {
        "wideHorizontalCorridor": {
          "ge": [
            "freeWidthH",
            6
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "wideHorizontalCorridor",
          "W"
        ]
      }
    }
  }
]
